// Decide o debounce e consolida (à prova de corrida):
// - buffer estável (nada chegou nos 15s) → consolida a lista inteira
// - buffer SUMIU (outra execução consolidou e apagou no meio da corrida) →
//   processa SÓ a própria mensagem (garante que nenhuma msg se perde)
// - chegou msg nova durante a espera → aborta; a execução mais nova assume
const toArr = (x) => {
  if (Array.isArray(x)) return x
  if (x === null || x === undefined || x === '') return []
  try { const p = JSON.parse(x); return Array.isArray(p) ? p : [String(x)] } catch { return [String(x)] }
}
const a1 = toArr($('LeBuffer1').item.json.propertyName)
const a2 = toArr($json.propertyName)
const w = $('Webhook_Bridge').first().json.body
let itens = null
if (JSON.stringify(a2) === JSON.stringify(a1)) itens = a2
else if (a2.length === 0) itens = [String(w.texto || '')]
if (!itens) return []
if (itens.length === 0) itens = [String(w.texto || '')]
const mensagem = itens.filter(Boolean).join('\n').trim()
if (!mensagem) return []
return [{ json: {
  mensagem_completa: mensagem,
  digits: String(w.digits || ''),
  nome: String(w.name || ''),
  conhecido: Boolean(w.conhecido),
} }]

