// Divide respostas longas em até 4 mensagens (padrão WhatsApp, sem paredão).
const texto = String($json.output || '').trim()
if (!texto) return []
const blocos = texto.split(/\n{2,}/).map((s) => s.trim()).filter(Boolean)
const partes = []
for (const b of blocos) {
  const i = partes.length - 1
  if (i >= 0 && (partes[i].length + b.length < 600 || partes.length >= 4)) partes[i] = partes[i] + '\n\n' + b
  else partes.push(b)
}
const digits = $('Consolida').first().json.digits
return partes.map((t) => ({ json: { texto: t, digits } }))
